def transform(grid):
    h, w = len(grid), len(grid[0])
    interior = [
        (r, c, grid[r][c])
        for r in range(3, h)
        for c in range(3, w)
        if grid[r][c] != 0
    ]

    period = None
    mapping = {}
    for p in range(2, 10):
        counts = {}
        colors = set()
        for r, c, color in interior:
            phase = (r + c) % p
            counts.setdefault(phase, {})
            counts[phase][color] = counts[phase].get(color, 0) + 1
            colors.add(color)

        if len(colors) < p:
            continue
        correct = sum(max(v.values()) for v in counts.values())
        accuracy = correct / len(interior) if interior else 0
        if accuracy >= 0.95:
            period = p
            mapping = {phase: max(v, key=v.get) for phase, v in counts.items()}
            break

    if period is None:
        period = 5
        counts = {}
        for r, c, color in interior:
            phase = (r + c) % period
            counts.setdefault(phase, {})
            counts[phase][color] = counts[phase].get(color, 0) + 1
        mapping = {phase: max(v, key=v.get) for phase, v in counts.items()}

    out = [row[:] for row in grid]
    fallback = max(mapping.values(), key=list(mapping.values()).count) if mapping else 1

    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                phase = (r + c) % period
                if phase in mapping:
                    out[r][c] = mapping[phase]
                elif mapping:
                    nearest = min(mapping, key=lambda k: min((phase-k) % period, (k-phase) % period))
                    out[r][c] = mapping[nearest]
                else:
                    out[r][c] = fallback
    return out
